def _parse_verdict(raw: str) -> float | None:
    """Extract pairwise verdict. Returns 1.0/0.0/0.5/None."""
    match = re.search(r"\[\[([ABC])\]\]", raw)
    if not match:
        return None
    v = match.group(1)
    if v == "A":
        return 1.0
    elif v == "B":
        return 0.0
    return 0.5


